int main(){try{
 Fixture f;CommonStore c(f.initial,f.catalog);FamilyDeathOriginRead no_death=[](const StableId&)->Outcome<std::optional<FamilyDeathOrigin>>{return {true,{}, {}};};BiologicalLegacyBasisContext x{c,*f.catalog,f.lineage,nullptr,nullptr,no_death};const auto before=encode_common_state(c.state());auto original=read_biological_child_origin(x,"parent","original_child");check(original.ok&&original.value&&original.value->kind==BiologicalChildOriginKind::installed_lineage&&original.value->original_catalog_actor_id=="original_child"&&original.value->birth_fact_id.empty(),"Installed source cannot masquerade as a birth fact");auto unknown=read_biological_child_origin(x,"stranger","original_child");check(unknown.ok&&!unknown.value,"unrecorded direct parent remains unknown");auto reverse=read_biological_child_origin(x,"original_child","parent");check(reverse.ok&&!reverse.value,"child cannot be called its own parent");check(!read_biological_legacy_basis(x,"parent","original_child").ok,"relation alone grants no death continuation");check(!read_biological_child_origin_before_fact(x,"parent","original_child",c.tick(),"missing").ok,"invented boundary refused");check(compare_boundary(before,encode_common_state(c.state())).exact(),"original source read changed state");
 auto original_tag=make_biological_control_origin(x,"parent","original_child");check(original_tag.ok&&original_tag.value.original_catalog_actor_id=="original_child"&&original_tag.value.birth_fact_id.empty(),"Installed permanent tag fabricated a fact");check(validate_biological_control_origin_before_decision(x,original_tag.value,c.tick(),"family_legacy:1").ok,"actual original consent boundary refused");check(!validate_biological_control_origin_before_decision(x,original_tag.value,c.tick(),"missing").ok,"nonexistent legacy boundary accepted");
 f.born();CommonStore dynamic(f.initial,f.catalog);BiologicalLegacyBasisContext y{dynamic,*f.catalog,f.lineage,&f.births,&f.life,no_death};const auto saved=encode_common_state(dynamic.state());auto born=read_biological_child_origin(y,"parent","actor:5");check(born.ok&&born.value&&born.value->kind==BiologicalChildOriginKind::recorded_birth&&born.value->birth_fact_id=="family_birth:4"&&born.value->creation_fact_id=="actor:5"&&born.value->original_catalog_actor_id.empty(),"dynamic origin did not keep true birth and creation");check(!read_biological_child_origin_before_fact(y,"parent","actor:5",3,"family_legacy:1").ok,"later newborn filled earlier same tick relation");check(read_biological_child_origin_before_fact(y,"parent","actor:5",3,"family_legacy:20").ok,"actual before-fact birth refused");auto birth_tag=make_biological_control_origin(y,"parent","actor:5");check(birth_tag.ok&&birth_tag.value.birth_fact_id=="family_birth:4","actual birth tag missing");check(validate_biological_control_origin_before_decision(y,birth_tag.value,3,"family_legacy:20").ok,"real birth before decision refused");auto fake_tag=birth_tag.value;fake_tag.birth_fact_id="family_birth:2";check(!validate_biological_control_origin_before_decision(y,fake_tag,3,"family_legacy:20").ok,"swapped actual birth source accepted");check(!validate_biological_control_origin_before_decision(y,birth_tag.value,3,"actor:5").ok,"actor creation used as a control decision boundary");auto absent=y;absent.births=nullptr;check(!read_biological_child_origin(absent,"parent","actor:5").ok,"selected Birth missing typed source fell back to header");dynamic.state().actors.find("actor:5")->birth_tick=2;check(!read_biological_child_origin(y,"parent","actor:5").ok,"forged birthday accepted");dynamic.state().actors.find("actor:5")->birth_tick=3;check(compare_boundary(saved,encode_common_state(dynamic.state())).exact(),"dynamic origin read wrote state");
 dynamic.state().actors.find("parent")->alive=false;dynamic.state().facts.insert("military:30",{"military:30","military_casualties","military"});FamilyDeathRecord d;d.actor_id="parent";d.scenario_id="scene";d.world_id=dynamic.state().identity.world_id;d.cause_fact_id="military:30";d.battle_id="battle";d.death_tick=d.recorded_tick=dynamic.tick();f.life.deaths.insert("family_death:31",d);dynamic.state().facts.insert("family_death:31",{"family_death:31","family_death","family_life"});dynamic.state().facts.insert("family_legacy:32",{"family_legacy:32","family_legacy_control_activated","family_legacy"});y.death_origin=[&](const StableId& id)->Outcome<std::optional<FamilyDeathOrigin>>{if(id=="parent")return {true,FamilyDeathOrigin{id,"military:30","battle",dynamic.tick()}, {}};return {true,{}, {}};};auto eligible=read_biological_legacy_basis(y,"parent","actor:5");check(eligible.ok&&eligible.value.relation.birth_fact_id=="family_birth:4"&&eligible.value.successor_birth_tick==3,"actual adult child original birth basis unavailable");auto historical=read_biological_legacy_basis_before_fact(y,"parent","actor:5",dynamic.tick(),"family_legacy:32");check(historical.ok&&historical.value.before_fact_id=="family_legacy:32"&&historical.value.relation.before_fact_id=="military:30","actual activation and original cause boundaries conflated");check(!read_biological_legacy_basis_before_fact(y,"parent","actor:5",dynamic.tick(),"military:30").ok,"cause itself cannot replace formal death registration");
 std::cout<<"BIOLOGICAL_LEGACY_BASIS "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
